package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*; @Entity @Table(name="customer_cart_item") public class CustomerCartItem {@Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="cart_item_id") private UUID id; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="cart_id",unique=true) private CustomerCart cart; @Column(name="retailer_id",nullable=false) private UUID retailerId; @Column(nullable=false) private int quantity; @Column(nullable=false,length=30) private String status="ACTIVE"; @Column(columnDefinition="TEXT") private String description; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; @PrePersist void add(){var now=OffsetDateTime.now();createdAt=now;updatedAt=now;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public CustomerCartItem(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public CustomerCart getCart(){return cart;} public void setCart(CustomerCart v){cart=v;} public UUID getRetailerId(){return retailerId;} public void setRetailerId(UUID v){retailerId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;}}